    derive: (i, deep) => {
      const p = (deep && deep.params) || {};
      const growth = p.growth || 1, k = p.peak || 3;
      const reqDay = i.dau * 1e6 * i.feeds * growth, req = reqDay / 86400, peakReq = req * k;
      const evDay = i.dau * 1e6 * i.evUser * growth, peakEv = (evDay / 86400) * k, scores = peakReq * i.cand;
      return { growth, k, reqDay, req, peakReq, evDay, peakEv, cand: i.cand, rankCap: i.rankCap, scores,
        rankers: Math.ceil(scores / i.rankCap / 0.7), evTB: (evDay * EV_KB) / 1e9, indexGB: (i.items * 1e6 * EMB_BYTES) / 1e9 };
    },

